import java.util.*;

public class Solution {
    private PriorityQueue<Long> small; // max-heap
    private PriorityQueue<Long> large; // min-heap
    private Map<Long, Integer> delayed;
    private int smallSize; // number of valid elements in small
    private int largeSize; // number of valid elements in large

    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] ans = new double[n - k + 1];
        small = new PriorityQueue<>(Collections.reverseOrder());
        large = new PriorityQueue<>();
        delayed = new HashMap<>();
        smallSize = 0;
        largeSize = 0;

        for (int i = 0; i < n; i++) {
            addNum((long) nums[i]);
            if (i >= k) {
                removeNum((long) nums[i - k]);
            }
            if (i >= k - 1) {
                ans[i - k + 1] = getMedian(k);
            }
        }
        return ans;
    }

    private void addNum(long num) {
        if (small.isEmpty() || num <= small.peek()) {
            small.offer(num);
            smallSize++;
        } else {
            large.offer(num);
            largeSize++;
        }
        rebalance();
    }

    private void removeNum(long num) {
        // mark for delayed removal
        delayed.put(num, delayed.getOrDefault(num, 0) + 1);
        // adjust sizes depending on where the number would be
        if (!small.isEmpty() && num <= small.peek()) {
            smallSize--;
            if (smallSize < 0) smallSize = 0; // safety
        } else {
            largeSize--;
            if (largeSize < 0) largeSize = 0;
        }
        // prune tops if necessary and rebalance
        prune(small);
        prune(large);
        rebalance();
    }

    private void rebalance() {
        // ensure smallSize >= largeSize and difference at most 1
        if (smallSize > largeSize + 1) {
            // move top from small to large
            prune(small);
            long val = small.poll();
            smallSize--;
            large.offer(val);
            largeSize++;
        } else if (smallSize < largeSize) {
            prune(large);
            long val = large.poll();
            largeSize--;
            small.offer(val);
            smallSize++;
        }
        // clean up tops
        prune(small);
        prune(large);
    }

    private void prune(PriorityQueue<Long> heap) {
        while (!heap.isEmpty()) {
            long top = heap.peek();
            Integer cnt = delayed.get(top);
            if (cnt == null || cnt == 0) break;
            // remove top and decrement delayed count
            heap.poll();
            if (cnt == 1) delayed.remove(top);
            else delayed.put(top, cnt - 1);
        }
    }

    private double getMedian(int k) {
        prune(small);
        prune(large);
        if ((k & 1) == 1) {
            return (double) small.peek();
        } else {
            return ((double) small.peek() + (double) large.peek()) / 2.0;
        }
    }
}

